css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .56); position: relative; overflow: hidden; }
.loader::before { content: ''; position: absolute; left: 0; bottom: calc(var(--loader-size) * -.46); width: var(--loader-size); height: var(--loader-size); border-radius: 50%; border: calc(var(--loader-size) * .08) solid color-mix(in srgb, var(--accent) 20%, transparent); border-top-color: var(--accent-2); border-left-color: var(--accent); box-sizing: border-box; }
.loader span { position: absolute; left: 50%; bottom: 6%; width: calc(var(--loader-size) * .035); height: 82%; margin-left: calc(var(--loader-size) * -.0175); background: var(--accent-2); border-radius: 3px; transform-origin: 50% 100%; animation: needle calc(var(--loader-speed) * 2.2) cubic-bezier(.5, 0, .5, 1) infinite; }
.loader::after { content: ''; position: absolute; left: 50%; bottom: 6%; width: calc(var(--loader-size) * .12); height: calc(var(--loader-size) * .12); transform: translate(-50%, 50%); border-radius: 50%; background: var(--accent-2); }
@keyframes needle { 0%, 100% { transform: rotate(-82deg); } 50% { transform: rotate(82deg); } }
